import { useEffect, useMemo, useState, useCallback, useRef } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  ShieldAlert, ExternalLink, Copy, Check, Search, RefreshCw,
  TrendingUp, AlertTriangle, Clock, Globe, Database, Zap,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { LiveSearchInput } from "@/components/LiveSearchInput";

// ── NVD CVE type ──────────────────────────────────────────────────────────────
type NvdCveRaw = {
  id: string;
  published: string;
  lastModified: string;
  vulnStatus: string;
  descriptions: { lang: string; value: string }[];
  metrics?: {
    cvssMetricV31?: { cvssData: { baseScore: number; baseSeverity: string; vectorString: string } }[];
    cvssMetricV30?: { cvssData: { baseScore: number; baseSeverity: string } }[];
    cvssMetricV2?:  { cvssData: { baseScore: number } }[];
  };
  references?: { url: string }[];
  weaknesses?: { description: { lang: string; value: string }[] }[];
};

function nvdScore(c: NvdCveRaw) {
  return c.metrics?.cvssMetricV31?.[0]?.cvssData.baseScore
      ?? c.metrics?.cvssMetricV30?.[0]?.cvssData.baseScore
      ?? c.metrics?.cvssMetricV2?.[0]?.cvssData.baseScore
      ?? null;
}
function nvdDesc(c: NvdCveRaw) {
  return c.descriptions.find(d => d.lang === "en")?.value || "";
}
function getNvdSev(c: NvdCveRaw) {
  const s = nvdScore(c);
  if (!s) return "info";
  if (s >= 9.0) return "critical";
  if (s >= 7.0) return "high";
  if (s >= 4.0) return "medium";
  return "low";
}

type ThreatItem = {
  id: string;
  title: string;
  link: string;
  severity: string;
  published_at: string;
  iocs: { cves?: string[]; ipv4?: string[]; sha256?: string[] } | null;
  source_name?: string;
};

type CVEEntry = {
  id: string;
  count: number;
  maxSev: string;
  firstSeen: string;
  lastSeen: string;
  items: ThreatItem[];
};

function CopyBtn({ value }: { value: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      onClick={(e) => {
        e.stopPropagation();
        navigator.clipboard.writeText(value).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        });
      }}
      className="shrink-0 rounded p-0.5 text-muted-foreground hover:text-foreground transition-colors"
      title="Copy CVE ID"
    >
      {copied ? <Check className="h-3 w-3 text-success" /> : <Copy className="h-3 w-3" />}
    </button>
  );
}

const SEV_ORDER = ["critical", "high", "medium", "low", "info"];

const SEV_STYLES: Record<string, string> = {
  critical: "bg-destructive/20 text-destructive border-destructive/40",
  high: "bg-orange-500/20 text-orange-400 border-orange-500/40",
  medium: "bg-yellow-500/20 text-yellow-400 border-yellow-500/40",
  low: "bg-blue-500/20 text-blue-400 border-blue-500/40",
  info: "bg-muted/30 text-muted-foreground border-border/40",
};

const SEV_DOT: Record<string, string> = {
  critical: "bg-destructive",
  high: "bg-orange-500",
  medium: "bg-yellow-500",
  low: "bg-blue-500",
  info: "bg-muted-foreground",
};

function maxSeverity(items: ThreatItem[]): string {
  for (const s of SEV_ORDER) {
    if (items.some((i) => i.severity === s)) return s;
  }
  return "info";
}

// CVSS score estimation based on severity — purely indicative
const CVSS_ESTIMATE: Record<string, string> = {
  critical: "9.0–10.0",
  high: "7.0–8.9",
  medium: "4.0–6.9",
  low: "0.1–3.9",
  info: "N/A",
};

const NVD_PAGE = 20;

export default function CVETracker() {
  const { toast } = useToast();
  const [mainTab, setMainTab] = useState<"intel" | "nvd">("intel");

  // ── Intel-feed tab state ───────────────────────────────────────────────────
  // `items` and `loading` are populated from useQuery below — see line ~191.
  const [items, setItems] = useState<ThreatItem[]>([]);
  const [search, setSearch] = useState("");
  const [sevFilter, setSevFilter] = useState("all");
  const [sortBy, setSortBy] = useState<"mentions" | "recent" | "severity">("mentions");
  const [selected, setSelected] = useState<CVEEntry | null>(null);
  const [page, setPage] = useState(0);
  const PAGE_SIZE = 30;

  // ── NVD full search state ──────────────────────────────────────────────────
  const [nvdQuery, setNvdQuery] = useState("");
  const [nvdResults, setNvdResults] = useState<NvdCveRaw[]>([]);
  const [nvdTotal, setNvdTotal] = useState(0);
  const [nvdPage, setNvdPage] = useState(0);
  const [nvdLoading, setNvdLoading] = useState(false);
  const [nvdSev, setNvdSev] = useState("all");
  const [nvdSelected, setNvdSelected] = useState<NvdCveRaw | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchNvd = useCallback(async (query: string, page: number, sev: string) => {
    if (!query.trim() && sev === "all") return;
    setNvdLoading(true);
    try {
      const params = new URLSearchParams({ resultsPerPage: String(NVD_PAGE), startIndex: String(page * NVD_PAGE) });
      if (query.trim()) {
        if (/^CVE-\d{4}-\d+$/i.test(query.trim())) {
          params.set("cveId", query.trim().toUpperCase());
        } else {
          params.set("keywordSearch", query.trim());
        }
      }
      if (sev !== "all") params.set("cvssV3Severity", sev.toUpperCase());

      const url = `https://services.nvd.nist.gov/rest/json/cves/2.0?${params}`;
      // Bulletproof: direct → Supabase proxy → public proxies → localStorage cache.
      const { fetchNvd } = await import("@/lib/nvd-client");
      const data: any = await fetchNvd(url);
      if (!data) {
        // All four paths down — show empty rather than crashing the page.
        setNvdResults([]);
        setNvdTotal(0);
      } else {
        setNvdResults((data.vulnerabilities || []).map((v: any) => v.cve));
        setNvdTotal(data.totalResults || 0);
      }
    } catch (err: any) {
      // Should never happen — fetchNvd swallows errors. Log and keep last results.
      console.error("[CVETracker] unexpected NVD error", err);
    }
    setNvdLoading(false);
  }, [toast]);

  // Debounced search on query change
  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setNvdPage(0);
      fetchNvd(nvdQuery, 0, nvdSev);
    }, 600);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [nvdQuery, nvdSev]); // eslint-disable-line react-hooks/exhaustive-deps

  // Refetch on page change
  useEffect(() => { fetchNvd(nvdQuery, nvdPage, nvdSev); }, [nvdPage]); // eslint-disable-line react-hooks/exhaustive-deps

  // TanStack Query — replaces manual useEffect + setState pattern
  const { data: rawItems = [], isLoading: loading, refetch } = useQuery({
    queryKey: ["threat_items", "cve_feed"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("threat_items")
        .select("id,title,link,severity,published_at,iocs,source_name,confidence_score,mitre_techniques")
        .not("iocs->cves", "is", null)
        .order("published_at", { ascending: false })
        .limit(1000);
      if (error) throw error;
      return (data || []).filter((i: any) => (i.iocs?.cves?.length ?? 0) > 0) as ThreatItem[];
    },
    staleTime: 5 * 60_000,
  });

  // Local DB cves table — enriched CVSS/EPSS/KEV data
  const { data: dbCVEs = [] } = useQuery({
    queryKey: ["cves", "all"],
    queryFn: async () => {
      const { data } = await supabase.from("cves").select("cve_id,cvss_v3_score,epss_score,kev_added,kev_due_date,kev_ransomware,description,severity,affected_products");
      return (data ?? []) as Array<{ cve_id: string; cvss_v3_score: number | null; epss_score: number | null; kev_added: boolean; kev_due_date: string | null; kev_ransomware: boolean; description: string | null; severity: string | null; affected_products: any[] }>;
    },
    staleTime: 30 * 60_000,
  });

  const dbCVEMap = useMemo(() => {
    const m = new Map<string, typeof dbCVEs[0]>();
    for (const c of dbCVEs) m.set(c.cve_id, c);
    return m;
  }, [dbCVEs]);

  const load = useCallback(() => { refetch(); }, [refetch]);
  useEffect(() => { load(); }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Sync rawItems (TanStack Query result) into items state used by downstream consumers
  useEffect(() => { if (rawItems.length) setItems(rawItems); }, [rawItems]);

  const cveMap = useMemo(() => {
    const map = new Map<string, CVEEntry>();
    for (const item of items) {
      for (const cve of item.iocs?.cves || []) {
        const existing = map.get(cve);
        if (existing) {
          existing.count++;
          existing.items.push(item);
          const ts = item.published_at;
          if (ts < existing.firstSeen) existing.firstSeen = ts;
          if (ts > existing.lastSeen) existing.lastSeen = ts;
        } else {
          map.set(cve, {
            id: cve,
            count: 1,
            maxSev: item.severity,
            firstSeen: item.published_at,
            lastSeen: item.published_at,
            items: [item],
          });
        }
      }
    }
    // Recalculate maxSev after aggregation
    for (const entry of map.values()) {
      entry.maxSev = maxSeverity(entry.items);
    }
    return [...map.values()];
  }, [items]);

  const filtered = useMemo(() => {
    let out = cveMap;
    if (sevFilter !== "all") out = out.filter((c) => c.maxSev === sevFilter);
    if (search.trim()) {
      const q = search.trim().toUpperCase();
      out = out.filter((c) => c.id.includes(q) || c.items.some((i) => i.title.toUpperCase().includes(q)));
    }
    if (sortBy === "mentions") out = [...out].sort((a, b) => b.count - a.count);
    else if (sortBy === "recent") out = [...out].sort((a, b) => b.lastSeen.localeCompare(a.lastSeen));
    else {
      out = [...out].sort((a, b) => SEV_ORDER.indexOf(a.maxSev) - SEV_ORDER.indexOf(b.maxSev));
    }
    return out;
  }, [cveMap, sevFilter, search, sortBy]);

  const paginated = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);

  const sevCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const c of cveMap) counts[c.maxSev] = (counts[c.maxSev] || 0) + 1;
    return counts;
  }, [cveMap]);

  const totalMentions = useMemo(() => cveMap.reduce((s, c) => s + c.count, 0), [cveMap]);

  return (
    <div className="container mx-auto px-4 py-8">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center gap-3 mb-2 flex-wrap">
          <ShieldAlert className="h-6 w-6 text-primary" />
          <h1 className="text-3xl font-bold tracking-tight">CVE Tracker</h1>
          <Badge variant="outline" className="text-[10px] border-primary/40 text-primary">
            NVD · {nvdTotal > 0 ? `${nvdTotal.toLocaleString()} results` : "200k+ CVEs"}
          </Badge>
          <Button size="sm" variant="outline" onClick={load} disabled={loading} className="ml-auto gap-1.5">
            <RefreshCw className={`h-3.5 w-3.5 ${loading ? "animate-spin" : ""}`} />
            Refresh Intel
          </Button>
        </div>
        <p className="text-muted-foreground text-sm">
          Two modes: <strong>Intel Feed</strong> — CVEs seen in threat reports · <strong>NVD Search</strong> — search all 200,000+ CVEs in the NVD database directly
        </p>
      </div>

      {/* Main tab selector */}
      <Tabs value={mainTab} onValueChange={v => setMainTab(v as any)} className="mb-0">
        <TabsList className="mb-6 bg-card/60">
          <TabsTrigger value="intel" className="gap-1.5">
            <Database className="h-3.5 w-3.5" /> Intel Feed ({cveMap.length} CVEs)
          </TabsTrigger>
          <TabsTrigger value="nvd" className="gap-1.5">
            <Zap className="h-3.5 w-3.5" /> NVD Full Search
            {nvdTotal > 0 && <Badge className="ml-1 text-[9px] bg-primary/20 text-primary border-primary/30 border">{nvdTotal.toLocaleString()}</Badge>}
          </TabsTrigger>
        </TabsList>

        {/* ── NVD Full Search Tab ──────────────────────────────────────────────── */}
        <TabsContent value="nvd">
          <div className="flex flex-wrap gap-3 mb-4">
            <div className="relative flex-1 min-w-60">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search CVE-XXXX-XXXX or keyword (e.g. log4j, apache, zero-day)…"
                value={nvdQuery}
                onChange={e => setNvdQuery(e.target.value)}
                className="pl-9"
                autoFocus
              />
            </div>
            <div className="flex gap-1">
              {["all","critical","high","medium","low"].map(s => (
                <Button key={s} size="sm" variant={nvdSev === s ? "default" : "outline"} onClick={() => setNvdSev(s)} className="text-xs capitalize">
                  {s}
                </Button>
              ))}
            </div>
          </div>

          {!nvdQuery.trim() && nvdSev === "all" ? (
            <div className="text-center py-20 text-muted-foreground">
              <Search className="h-10 w-10 mx-auto mb-3 opacity-20" />
              <p className="text-base font-medium">Search across 200,000+ CVEs</p>
              <p className="text-sm mt-1">Type a CVE ID, product name, or keyword to search the NVD database</p>
              <div className="flex flex-wrap gap-2 justify-center mt-4">
                {["log4j","apache","windows","zero-day","CVE-2024-3400","CVE-2021-44228","cisco","openssl"].map(ex => (
                  <button key={ex} onClick={() => setNvdQuery(ex)} className="rounded-full px-3 py-1 text-xs border border-border/60 bg-card/40 hover:border-primary/40 hover:text-primary transition-colors font-mono">
                    {ex}
                  </button>
                ))}
              </div>
            </div>
          ) : nvdLoading ? (
            <div className="text-center py-16 text-muted-foreground">
              <RefreshCw className="h-8 w-8 mx-auto mb-3 animate-spin text-primary" />
              Querying NVD database…
            </div>
          ) : nvdResults.length === 0 ? (
            <div className="text-center py-16 text-muted-foreground">No CVEs found. Try a different keyword.</div>
          ) : (
            <>
              <p className="text-xs text-muted-foreground mb-3">
                Showing {nvdPage * NVD_PAGE + 1}–{Math.min((nvdPage + 1) * NVD_PAGE, nvdTotal)} of {nvdTotal.toLocaleString()} results
              </p>
              <div className="grid gap-3 lg:grid-cols-[1fr_420px]">
                <div className="space-y-2">
                  {nvdResults.map(cve => {
                    const score = nvdScore(cve);
                    const sev = getNvdSev(cve);
                    const desc = nvdDesc(cve);
                    const isSelected = nvdSelected?.id === cve.id;
                    return (
                      <div
                        key={cve.id}
                        onClick={() => setNvdSelected(isSelected ? null : cve)}
                        className={`rounded-lg border p-3 cursor-pointer transition-all ${isSelected ? "border-primary/60 bg-primary/5 ring-1 ring-primary/30" : "border-border/60 bg-card/40 hover:border-primary/30"}`}
                      >
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className={`h-2 w-2 rounded-full shrink-0 ${SEV_DOT[sev] || "bg-muted-foreground"}`} />
                          <span className="font-mono font-semibold text-sm">{cve.id}</span>
                          <CopyBtn value={cve.id} />
                          <Badge variant="outline" className={`text-[10px] ${SEV_STYLES[sev]}`}>{sev.toUpperCase()}</Badge>
                          {score != null && <Badge variant="outline" className="font-mono text-[10px]">CVSS {score.toFixed(1)}</Badge>}
                          <span className="text-[10px] text-muted-foreground ml-auto">{new Date(cve.published).toLocaleDateString()}</span>
                        </div>
                        <p className="mt-1.5 ml-4 text-xs text-muted-foreground line-clamp-2">{desc}</p>
                      </div>
                    );
                  })}
                </div>

                {/* NVD detail panel */}
                <div>
                  {nvdSelected ? (
                    <Card className="sticky top-20 border-primary/30 bg-card/80 backdrop-blur">
                      <CardHeader className="pb-3">
                        <div className="flex items-start gap-2 flex-wrap">
                          <CardTitle className="font-mono text-lg">{nvdSelected.id}</CardTitle>
                          <Badge variant="outline" className={`${SEV_STYLES[getNvdSev(nvdSelected)]} text-[11px]`}>
                            {getNvdSev(nvdSelected).toUpperCase()}
                          </Badge>
                          {nvdScore(nvdSelected) && (
                            <Badge variant="outline" className="font-mono text-[11px]">
                              CVSS {nvdScore(nvdSelected)?.toFixed(1)}
                            </Badge>
                          )}
                        </div>
                        <p className="text-xs text-muted-foreground mt-1">{nvdDesc(nvdSelected)}</p>
                      </CardHeader>
                      <CardContent className="space-y-3">
                        <div className="text-xs text-muted-foreground space-y-1">
                          <div>Published: {new Date(nvdSelected.published).toLocaleString()}</div>
                          <div>Modified: {new Date(nvdSelected.lastModified).toLocaleString()}</div>
                          <div>Status: {nvdSelected.vulnStatus}</div>
                          {nvdSelected.weaknesses?.[0]?.description?.find(d => d.lang === "en") && (
                            <div>CWE: {nvdSelected.weaknesses[0].description.find(d => d.lang === "en")?.value}</div>
                          )}
                        </div>
                        <div>
                          <p className="text-[10px] uppercase tracking-wide text-muted-foreground mb-2">Databases</p>
                          <div className="grid grid-cols-2 gap-1.5">
                            {[
                              { label: "NVD", url: `https://nvd.nist.gov/vuln/detail/${nvdSelected.id}` },
                              { label: "MITRE", url: `https://cve.mitre.org/cgi-bin/cvename.cgi?name=${nvdSelected.id}` },
                              { label: "Vulners", url: `https://vulners.com/cve/${nvdSelected.id}` },
                              { label: "OSV.dev", url: `https://osv.dev/vulnerability/${nvdSelected.id}` },
                              { label: "Exploit-DB", url: `https://www.exploit-db.com/search?cve=${nvdSelected.id.replace("CVE-","")}` },
                              { label: "GitHub PoC", url: `https://github.com/search?q=${nvdSelected.id}&type=repositories` },
                              { label: "AttackerKB", url: `https://attackerkb.com/search?q=${nvdSelected.id}` },
                              { label: "IOC Lookup", url: `/lookup?q=${nvdSelected.id}` },
                            ].map(l => (
                              <a key={l.label} href={l.url} target="_blank" rel="noopener noreferrer"
                                className="flex items-center gap-1 rounded px-2 py-1.5 text-xs border border-border/60 bg-card/40 hover:border-primary/40 hover:bg-primary/5 transition-all">
                                <ExternalLink className="h-3 w-3 text-muted-foreground" />{l.label}
                              </a>
                            ))}
                          </div>
                        </div>
                        {nvdSelected.references && nvdSelected.references.length > 0 && (
                          <div>
                            <p className="text-[10px] uppercase tracking-wide text-muted-foreground mb-2">References</p>
                            <div className="space-y-1 max-h-40 overflow-y-auto">
                              {nvdSelected.references.slice(0, 8).map((r, i) => (
                                <a key={i} href={r.url} target="_blank" rel="noopener noreferrer"
                                  className="block text-[10px] text-primary hover:underline truncate">{r.url}</a>
                              ))}
                            </div>
                          </div>
                        )}
                        <Button size="sm" variant="outline" className="w-full gap-2" onClick={() => navigator.clipboard.writeText(nvdSelected.id)}>
                          <Copy className="h-3.5 w-3.5" /> Copy {nvdSelected.id}
                        </Button>
                      </CardContent>
                    </Card>
                  ) : (
                    <div className="sticky top-20 rounded-lg border border-dashed border-border/40 p-8 text-center text-muted-foreground">
                      <ShieldAlert className="h-8 w-8 mx-auto mb-3 opacity-30" />
                      <p className="text-sm">Click any CVE to see details</p>
                    </div>
                  )}
                </div>
              </div>

              {/* NVD Pagination */}
              {nvdTotal > NVD_PAGE && (
                <div className="flex items-center justify-center gap-2 mt-4">
                  <Button size="sm" variant="outline" onClick={() => setNvdPage(p => Math.max(0, p-1))} disabled={nvdPage === 0}>Previous</Button>
                  <span className="text-xs text-muted-foreground">
                    Page {nvdPage + 1} of {Math.ceil(nvdTotal / NVD_PAGE)} ({nvdTotal.toLocaleString()} total)
                  </span>
                  <Button size="sm" variant="outline" onClick={() => setNvdPage(p => p + 1)} disabled={(nvdPage + 1) * NVD_PAGE >= nvdTotal}>Next</Button>
                </div>
              )}
            </>
          )}
        </TabsContent>

        {/* ── Intel Feed Tab ───────────────────────────────────────────────────── */}
        <TabsContent value="intel">


      {/* KPI row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        <Card className="border-border/60 bg-card/60">
          <CardContent className="p-4">
            <div className="text-2xl font-bold tabular-nums text-primary">{cveMap.length}</div>
            <div className="text-xs text-muted-foreground mt-0.5 flex items-center gap-1">
              <TrendingUp className="h-3 w-3" /> Unique CVEs
            </div>
          </CardContent>
        </Card>
        <Card className="border-border/60 bg-card/60">
          <CardContent className="p-4">
            <div className="text-2xl font-bold tabular-nums text-destructive">{sevCounts.critical || 0}</div>
            <div className="text-xs text-muted-foreground mt-0.5 flex items-center gap-1">
              <AlertTriangle className="h-3 w-3" /> Critical CVEs
            </div>
          </CardContent>
        </Card>
        <Card className="border-border/60 bg-card/60">
          <CardContent className="p-4">
            <div className="text-2xl font-bold tabular-nums">{totalMentions}</div>
            <div className="text-xs text-muted-foreground mt-0.5 flex items-center gap-1">
              <Globe className="h-3 w-3" /> Total Mentions
            </div>
          </CardContent>
        </Card>
        <Card className="border-border/60 bg-card/60">
          <CardContent className="p-4">
            <div className="text-2xl font-bold tabular-nums text-orange-400">{sevCounts.high || 0}</div>
            <div className="text-xs text-muted-foreground mt-0.5 flex items-center gap-1">
              <Clock className="h-3 w-3" /> High Severity
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Severity filter chips */}
      <div className="flex flex-wrap gap-2 mb-4">
        {["all", "critical", "high", "medium", "low"].map((s) => (
          <button
            key={s}
            onClick={() => { setSevFilter(s); setPage(0); }}
            className={`rounded-full px-3 py-1 text-xs font-medium border transition-all ${
              sevFilter === s
                ? s === "all"
                  ? "bg-primary text-primary-foreground border-primary"
                  : SEV_STYLES[s] + " ring-1 ring-current"
                : "border-border/60 bg-card/40 text-muted-foreground hover:border-primary/40"
            }`}
          >
            {s === "all" ? "All" : s.charAt(0).toUpperCase() + s.slice(1)}
            {s !== "all" && sevCounts[s] ? ` (${sevCounts[s]})` : ""}
          </button>
        ))}
      </div>

      {/* Search + sort */}
      <div className="flex flex-wrap gap-3 mb-6">
        <div className="relative flex-1 min-w-48">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search CVE-XXXX-XXXXX or keyword..."
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(0); }}
            className="pl-9"
          />
        </div>
        <div className="flex gap-1.5">
          {(["mentions", "recent", "severity"] as const).map((s) => (
            <Button
              key={s}
              size="sm"
              variant={sortBy === s ? "default" : "outline"}
              onClick={() => setSortBy(s)}
              className="text-xs capitalize"
            >
              {s}
            </Button>
          ))}
        </div>
      </div>

      <div className="grid gap-4 lg:grid-cols-[1fr_380px]">
        {/* CVE List */}
        <div>
          {loading ? (
            <div className="text-center py-16 text-muted-foreground">Loading CVE data…</div>
          ) : filtered.length === 0 ? (
            <div className="text-center py-16 text-muted-foreground">No CVEs found matching your criteria.</div>
          ) : (
            <>
              <div className="space-y-2">
                {paginated.map((cve) => (
                  <div
                    key={cve.id}
                    onClick={() => setSelected(selected?.id === cve.id ? null : cve)}
                    className={`rounded-lg border p-3 cursor-pointer transition-all ${
                      selected?.id === cve.id
                        ? "border-primary/60 bg-primary/5 ring-1 ring-primary/30"
                        : "border-border/60 bg-card/40 hover:border-primary/30"
                    }`}
                  >
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className={`h-2 w-2 rounded-full shrink-0 ${SEV_DOT[cve.maxSev] || "bg-muted-foreground"}`} />
                      <span className="font-mono font-semibold text-sm">{cve.id}</span>
                      <CopyBtn value={cve.id} />
                      <Badge variant="outline" className={`text-[10px] ${SEV_STYLES[cve.maxSev]}`}>
                        {cve.maxSev.toUpperCase()}
                      </Badge>
                      <span className="text-xs text-muted-foreground ml-auto">
                        CVSS ~{CVSS_ESTIMATE[cve.maxSev]}
                      </span>
                      <Badge variant="secondary" className="text-[10px]">
                        {cve.count} mention{cve.count > 1 ? "s" : ""}
                      </Badge>
                    </div>
                    <div className="mt-1.5 ml-4 line-clamp-1 text-xs text-muted-foreground">
                      {cve.items[0]?.title}
                    </div>
                    <div className="mt-1 ml-4 flex items-center gap-3 text-[10px] text-muted-foreground">
                      <span>First: {new Date(cve.firstSeen).toLocaleDateString()}</span>
                      <span>Last: {new Date(cve.lastSeen).toLocaleDateString()}</span>
                      {cve.items[0]?.source_name && <span className="truncate">{cve.items[0].source_name}</span>}
                    </div>
                  </div>
                ))}
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex items-center justify-center gap-2 mt-4">
                  <Button
                    size="sm" variant="outline"
                    onClick={() => setPage((p) => Math.max(0, p - 1))}
                    disabled={page === 0}
                  >
                    Previous
                  </Button>
                  <span className="text-xs text-muted-foreground">
                    Page {page + 1} of {totalPages} ({filtered.length} CVEs)
                  </span>
                  <Button
                    size="sm" variant="outline"
                    onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
                    disabled={page >= totalPages - 1}
                  >
                    Next
                  </Button>
                </div>
              )}
            </>
          )}
        </div>

        {/* Detail panel */}
        <div>
          {selected ? (
            <Card className="sticky top-20 border-primary/30 bg-card/80 backdrop-blur">
              <CardHeader className="pb-3">
                <div className="flex items-start gap-2 flex-wrap">
                  <CardTitle className="font-mono text-lg">{selected.id}</CardTitle>
                  <Badge variant="outline" className={`${SEV_STYLES[selected.maxSev]} text-[11px]`}>
                    {selected.maxSev.toUpperCase()}
                  </Badge>
                </div>
                <div className="text-xs text-muted-foreground flex flex-wrap gap-3 items-center mt-1">
                  {(() => {
                    const db = dbCVEMap.get(selected.id);
                    return db ? (
                      <>
                        {db.cvss_v3_score != null && (
                          <span>CVSS v3: <strong className="text-foreground">{db.cvss_v3_score.toFixed(1)}</strong></span>
                        )}
                        {db.epss_score != null && (
                          <span>EPSS: <strong className="text-foreground">{(db.epss_score * 100).toFixed(2)}%</strong></span>
                        )}
                        {db.kev_added && (
                          <Badge className="bg-red-500/20 text-red-400 border-red-500/40 text-[9px]">
                            🔴 CISA KEV{db.kev_ransomware ? " · Ransomware" : ""}
                          </Badge>
                        )}
                      </>
                    ) : (
                      <span>CVSS estimate: ~{CVSS_ESTIMATE[selected.maxSev]}</span>
                    );
                  })()}
                  <span className="text-muted-foreground">&bull; {selected.count} source mention{selected.count > 1 ? "s" : ""}</span>
                </div>
              </CardHeader>
              <CardContent className="space-y-4">
                {/* Lookup Links */}
                <div>
                  <p className="text-[10px] uppercase tracking-wide text-muted-foreground mb-2">Official Databases</p>
                  <div className="grid grid-cols-2 gap-2">
                    {[
                      { label: "NVD / NIST", url: `https://nvd.nist.gov/vuln/detail/${selected.id}` },
                      { label: "MITRE CVE", url: `https://cve.mitre.org/cgi-bin/cvename.cgi?name=${selected.id}` },
                      { label: "Vulners", url: `https://vulners.com/cve/${selected.id}` },
                      { label: "OSV.dev", url: `https://osv.dev/vulnerability/${selected.id}` },
                      { label: "VulDB", url: `https://vuldb.com/?search=${selected.id}` },
                      { label: "Exploit-DB", url: `https://www.exploit-db.com/search?cve=${selected.id.replace("CVE-", "")}` },
                      { label: "GitHub Advisories", url: `https://github.com/advisories?query=${selected.id}` },
                      { label: "Packet Storm", url: `https://packetstormsecurity.com/search/?q=${selected.id}` },
                    ].map((l) => (
                      <a
                        key={l.label}
                        href={l.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1.5 rounded px-2.5 py-1.5 text-xs border border-border/60 bg-card/40 hover:border-primary/40 hover:bg-primary/5 transition-all"
                      >
                        <ExternalLink className="h-3 w-3 text-muted-foreground shrink-0" />
                        {l.label}
                      </a>
                    ))}
                  </div>
                </div>

                {/* Exploit Availability */}
                <div>
                  <p className="text-[10px] uppercase tracking-wide text-muted-foreground mb-2">Exploit Search</p>
                  <div className="grid grid-cols-2 gap-2">
                    {[
                      { label: "Metasploit", url: `https://www.rapid7.com/db/?q=${selected.id}&type=nexpose` },
                      { label: "PoC GitHub", url: `https://github.com/search?q=${selected.id}&type=repositories` },
                      { label: "Nuclei Templates", url: `https://github.com/projectdiscovery/nuclei-templates/search?q=${selected.id}` },
                      { label: "AttackerKB", url: `https://attackerkb.com/search?q=${selected.id}` },
                    ].map((l) => (
                      <a
                        key={l.label}
                        href={l.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1.5 rounded px-2.5 py-1.5 text-xs border border-border/60 bg-card/40 hover:border-orange-500/40 hover:bg-orange-500/5 transition-all text-orange-400/80"
                      >
                        <ExternalLink className="h-3 w-3 shrink-0" />
                        {l.label}
                      </a>
                    ))}
                  </div>
                </div>

                {/* Timeline */}
                <div>
                  <p className="text-[10px] uppercase tracking-wide text-muted-foreground mb-2">
                    Intelligence ({selected.count} source{selected.count > 1 ? "s" : ""})
                  </p>
                  <div className="space-y-2 max-h-64 overflow-y-auto pr-1">
                    {selected.items.map((item) => (
                      <a
                        key={item.id}
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex flex-col gap-0.5 rounded px-2.5 py-2 border border-border/40 bg-card/20 hover:border-primary/30 hover:bg-primary/5 transition-all group"
                      >
                        <div className="flex items-center gap-1.5">
                          <span className={`h-1.5 w-1.5 rounded-full shrink-0 ${SEV_DOT[item.severity] || "bg-muted-foreground"}`} />
                          <span className="text-xs font-medium line-clamp-1 group-hover:text-primary transition-colors">
                            {item.title}
                          </span>
                          <ExternalLink className="h-3 w-3 shrink-0 ml-auto text-muted-foreground" />
                        </div>
                        <div className="flex gap-2 text-[10px] text-muted-foreground ml-3">
                          <span>{new Date(item.published_at).toLocaleDateString()}</span>
                          {item.source_name && <span className="truncate">{item.source_name}</span>}
                        </div>
                      </a>
                    ))}
                  </div>
                </div>

                {/* Copy button */}
                <Button
                  size="sm"
                  variant="outline"
                  className="w-full gap-2"
                  onClick={() => navigator.clipboard.writeText(selected.id)}
                >
                  <Copy className="h-3.5 w-3.5" />
                  Copy {selected.id}
                </Button>
              </CardContent>
            </Card>
          ) : (
            <div className="sticky top-20 rounded-lg border border-dashed border-border/40 p-8 text-center text-muted-foreground">
              <ShieldAlert className="h-8 w-8 mx-auto mb-3 opacity-30" />
              <p className="text-sm">Select a CVE to see details, lookup links, and exploit search.</p>
            </div>
          )}
        </div>
      </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}
